      "App.jsx": "import React from 'react';\n\n// Child component receiving user details via props\nfunction ProfileCard(props) {\n  return (\n    <div className=\"card\">\n      <h3>Profile Card</h3>\n      <p><strong>Name:</strong> {props.name}</p>\n      <p><strong>Age:</strong> {props.age}</p>\n      <p><strong>Email:</strong> {props.email}</p>\n      <p><strong>Course:</strong> {props.course}</p>\n      <p><strong>Subject:</strong> {props.subject}</p>\n      <p><strong>Roll No.:</strong> {props.rollNo}</p>\n    </div>\n  );\n}\n\n// Parent App component passing props to ProfileCard\nfunction App() {\n  return (\n    <div className=\"container\">\n      <h1> Student Id</h1>\n      <hr />\n\n      <ProfileCard\n        name=\"Chandan Gopal Tiwadi\"\n        age={20}\n        email=\"chandan.tiwadi@example.com\"\n        course=\"B.Sc. IT\"\n        subject=\"ReactJs\"\n        rollNo={57}\n      />\n    </div>\n  );\n}\n\nexport default App;\n",
