    "title": "Current Date and Time",
    "description": "Develop a component that displays the current date and time using JavaScript and React.",
    "files": {
      "App.css": ".counter {\r\n    font-size: 16px;\r\n    padding: 5px 10px;\r\n    border-radius: 5px;\r\n    color: var(--accent);\r\n    background: var(--accent-bg);\r\n    border: 2px solid transparent;\r\n    transition: border-color 0.3s;\r\n    margin-bottom: 24px;\r\n\r\n    &:hover {\r\n        border-color: var(--accent-border);\r\n    }\r\n\r\n    &:focus-visible {\r\n        outline: 2px solid var(--accent);\r\n        outline-offset: 2px;\r\n    }\r\n}\r\n\r\n.hero {\r\n    position: relative;\r\n\r\n    .base,\r\n    .framework,\r\n    .vite {\r\n        inset-inline: 0;\r\n        margin: 0 auto;\r\n    }\r\n\r\n    .base {\r\n        width: 170px;\r\n        position: relative;\r\n        z-index: 0;\r\n    }\r\n\r\n    .framework,\r\n    .vite {\r\n        position: absolute;\r\n    }\r\n\r\n    .framework {\r\n        z-index: 1;\r\n        top: 34px;\r\n        height: 28px;\r\n        transform: perspective(2000px) rotateZ(300deg) rotateX(44deg) rotateY(39deg) scale(1.4);\r\n    }\r\n\r\n    .vite {\r\n        z-index: 0;\r\n        top: 107px;\r\n        height: 26px;\r\n        width: auto;\r\n        transform: perspective(2000px) rotateZ(300deg) rotateX(40deg) rotateY(39deg) scale(0.8);\r\n    }\r\n}\r\n\r\n#center {\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 25px;\r\n    place-content: center;\r\n    place-items: center;\r\n    flex-grow: 1;\r\n\r\n    @media (max-width: 1024px) {\r\n        padding: 32px 20px 24px;\r\n        gap: 18px;\r\n    }\r\n}\r\n\r\n#next-steps {\r\n    display: flex;\r\n    border-top: 1px solid var(--border);\r\n    text-align: left;\r\n\r\n    &>div {\r\n        flex: 1 1 0;\r\n        padding: 32px;\r\n\r\n        @media (max-width: 1024px) {\r\n            padding: 24px 20px;\r\n        }\r\n    }\r\n\r\n    .icon {\r\n        margin-bottom: 16px;\r\n        width: 22px;\r\n        height: 22px;\r\n    }\r\n\r\n    @media (max-width: 1024px) {\r\n        flex-direction: column;\r\n        text-align: center;\r\n    }\r\n}\r\n\r\n#docs {\r\n    border-right: 1px solid var(--border);\r\n\r\n    @media (max-width: 1024px) {\r\n        border-right: none;\r\n        border-bottom: 1px solid var(--border);\r\n    }\r\n}\r\n\r\n#next-steps ul {\r\n    list-style: none;\r\n    padding: 0;\r\n    display: flex;\r\n    gap: 8px;\r\n    margin: 32px 0 0;\r\n\r\n    .logo {\r\n        height: 18px;\r\n    }\r\n\r\n    a {\r\n        color: var(--text-h);\r\n        font-size: 16px;\r\n        border-radius: 6px;\r\n        background: var(--social-bg);\r\n        display: flex;\r\n        padding: 6px 12px;\r\n        align-items: center;\r\n        gap: 8px;\r\n        text-decoration: none;\r\n        transition: box-shadow 0.3s;\r\n\r\n        &:hover {\r\n            box-shadow: var(--shadow);\r\n        }\r\n\r\n        .button-icon {\r\n            height: 18px;\r\n            width: 18px;\r\n        }\r\n    }\r\n\r\n    @media (max-width: 1024px) {\r\n        margin-top: 20px;\r\n        flex-wrap: wrap;\r\n        justify-content: center;\r\n\r\n        li {\r\n            flex: 1 1 calc(50% - 8px);\r\n        }\r\n\r\n        a {\r\n            width: 100%;\r\n            justify-content: center;\r\n            box-sizing: border-box;\r\n        }\r\n    }\r\n}\r\n\r\n#spacer {\r\n    height: 88px;\r\n    border-top: 1px solid var(--border);\r\n\r\n    @media (max-width: 1024px) {\r\n        height: 48px;\r\n    }\r\n}\r\n\r\n.ticks {\r\n    position: relative;\r\n    width: 100%;\r\n\r\n    &::before,\r\n    &::after {\r\n        content: '';\r\n        position: absolute;\r\n        top: -4.5px;\r\n        border: 5px solid transparent;\r\n    }\r\n\r\n    &::before {\r\n        left: 0;\r\n        border-left-color: var(--border);\r\n    }\r\n\r\n    &::after {\r\n        right: 0;\r\n        border-right-color: var(--border);\r\n    }\r\n}",
      "App.jsx": "import { useState, useEffect } from \"react\";\n\nfunction App() {\n  const [currentDateTime, setCurrentDateTime] = useState(new Date());\n\n  useEffect(() => {\n    const timer = setInterval(() => {\n      setCurrentDateTime(new Date());\n    }, 1000);\n\n    return () => clearInterval(timer);\n  }, []);\n\n  return (\n    <div style={{ textAlign: \"center\", marginTop: \"50px\" }}>\n      <h1>Current Date and Time</h1>\n      <h2>{currentDateTime.toLocaleDateString()}</h2>\n      <h2>{currentDateTime.toLocaleTimeString()}</h2>\n    </div>\n  );\n}\n\nexport default App;",
      "index.css": "* {\n  margin: 0;\n  padding: 0;\n  box-sizing: border-box;\n}\n\nbody {\n  font-family: Arial, Helvetica, sans-serif;\n  background: linear-gradient(135deg, #4facfe, #00f2fe);\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  min-height: 100vh;\n}\n\n#root {\n  width: 100%;\n}\n\ndiv {\n  background: #ffffff;\n  padding: 40px;\n  border-radius: 12px;\n  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.2);\n  text-align: center;\n  max-width: 500px;\n  margin: auto;\n}\n\nh1 {\n  color: #333;\n  margin-bottom: 20px;\n}\n\nh2 {\n  color: #555;\n  margin: 10px 0;\n  font-size: 1.5rem;\n}",
      "Main.jsx": "import React from \"react\";\nimport ReactDOM from \"react-dom/client\";\nimport App from \"./App\";\nimport \"./index.css\";\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(\n  <React.StrictMode>\n    <App />\n  </React.StrictMode>\n);\n"
    }
