  {
    "id": 14,
    "num": "14",
    "title": "Fetch Data from Public API",
    "description": "Create an app that fetches and displays user data from a public API (e.g., JSONPlaceholder or Reqres).",
    "files": {
      "App.jsx": "import { useState, useEffect } from \"react\";\nimport \"./index.css\";\n\nfunction App() {\n  const [users, setUsers] = useState([]);\n  const [loading, setLoading] = useState(true);\n\n  useEffect(() => {\n    const fetchUsers = async () => {\n      try {\n        const response = await fetch(\n          \"https://jsonplaceholder.typicode.com/users\"\n        );\n        const data = await response.json();\n        setUsers(data);\n      } catch (error) {\n        console.log(\"Error:\", error);\n      } finally {\n        setLoading(false);\n      }\n    };\n\n    fetchUsers();\n  }, []);\n\n  return (\n    <div className=\"container\">\n      <h1>🌐 API Data Fetching</h1>\n      <p className=\"subtitle\">User Details from JSONPlaceholder API</p>\n\n      {loading ? (\n        <div className=\"loader\"></div>\n      ) : (\n        <div className=\"card-container\">\n          {users.map((user) => (\n            <div className=\"card\" key={user.id}>\n              <div className=\"avatar\">\n                {user.name.charAt(0)}\n              </div>\n\n              <h2>{user.name}</h2>\n\n              <p>\n                <strong>📧 Email:</strong><br />\n                {user.email}\n              </p>\n\n              <p>\n                <strong>📞 Phone:</strong><br />\n                {user.phone}\n              </p>\n\n              <p>\n                <strong>🌍 Website:</strong><br />\n                {user.website}\n              </p>\n\n              <button>View Profile</button>\n            </div>\n          ))}\n        </div>\n      )}\n    </div>\n  );\n}\n\nexport default App;",
      "index.css": "body {\n  margin: 0;\n  font-family: Arial, sans-serif;\n  background: #f5f5f5;\n}\n\n.container {\n  width: 90%;\n  max-width: 1100px;\n  margin: 30px auto;\n  text-align: center;\n}\n\nh1 {\n  margin-bottom: 5px;\n}\n\n.subtitle {\n  color: #666;\n  margin-bottom: 30px;\n}\n\n.card-container {\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: center;\n  gap: 20px;\n}\n\n.card {\n  background: white;\n  width: 250px;\n  padding: 20px;\n  border: 1px solid #ddd;\n  border-radius: 8px;\n  text-align: left;\n}\n\n.avatar {\n  width: 50px;\n  height: 50px;\n  margin: 0 auto 15px;\n  border-radius: 50%;\n  background: #ddd;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 22px;\n  font-weight: bold;\n}\n\n.card button {\n  width: 100%;\n  padding: 8px;\n  border: none;\n  border-radius: 5px;\n  background: #333;\n  color: white;\n  cursor: pointer;\n}\n\n.card button:hover {\n  background: #555;\n}\n\n@keyframes spin {\n  to {\n    transform: rotate(360deg);\n  }\n}",
      "Main.jsx": "import React from \"react\";\nimport ReactDOM from \"react-dom/client\";\nimport App from \"./App\";\nimport \"./index.css\";\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(\n  <React.StrictMode>\n    <App />\n  </React.StrictMode>\n);\n"
    }
  },
  {
    "id": 15,
    "num": "15",
    "title": "Context API - Global Theme",
    "description": "Use Context API to create a global theme or authentication status across the application.",
    "files": {
      "App.jsx": "import React, { createContext, useContext, useState } from 'react';\n\n// 1. Create Theme Context\nconst ThemeContext = createContext();\n\n// 2. Theme Provider Component\nfunction ThemeProvider({ children }) {\n  const [theme, setTheme] = useState('light');\n\n  const toggleTheme = () => {\n    setTheme((prevTheme) => (prevTheme === 'light' ? 'dark' : 'light'));\n  };\n\n  return (\n    <ThemeContext.Provider value={{ theme, toggleTheme }}>\n      {children}\n    </ThemeContext.Provider>\n  );\n}\n\n// 3. Child Component consuming Context for Theme Toggle\nfunction ThemeToggle() {\n  const { theme, toggleTheme } = useContext(ThemeContext);\n  return (\n    <div style={{ margin: '15px 0' }}>\n      <p>Current Theme: <strong>{theme.toUpperCase()}</strong></p>\n      <button onClick={toggleTheme}>\n        Switch to {theme === 'light' ? 'Dark' : 'Light'} Mode\n      </button>\n    </div>\n  );\n}\n\n// 4. Child Component consuming Context for Profile Card Styling\nfunction ProfileCard() {\n  const { theme } = useContext(ThemeContext);\n  const isDark = theme === 'dark';\n\n  const cardStyle = {\n    backgroundColor: isDark ? '#333333' : '#f4f4f4',\n    color: isDark ? '#ffffff' : '#333333',\n    borderColor: isDark ? '#555555' : '#cccccc',\n  };\n\n}\nfunction PracticalContent() {\n  const { theme } = useContext(ThemeContext);\n  const isDark = theme === 'dark';\n\n  const containerStyle = {\n    backgroundColor: isDark ? '#222222' : '#ffffff',\n    color: isDark ? '#ffffff' : '#333333',\n    borderColor: isDark ? '#444444' : '#dddddd',\n  };\n\n  return (\n    <div className=\"container\" style={containerStyle}>\n      <h1 style={{ color: isDark ? '#ffffff' : '#222222' }}>\n        Global Theme Context API\n      </h1>\n      <hr />\n\n      <p>Demonstrating <code>createContext()</code> and <code>useContext()</code> across child components.</p>\n\n      <ThemeToggle />\n      <ProfileCard />\n    </div>\n  );\n}\nfunction App() {\n  return (\n    <ThemeProvider>\n      <PracticalContent />\n    </ThemeProvider>\n  );\n}\n\nexport default App;\n",
      "index.css": "* {\n  box-sizing: border-box;\n}\n\nbody {\n  margin: 0;\n  font-family: Arial, sans-serif;\n  background: #f5f5f5;\n}\n\n.container {\n  min-height: 100vh;\n  width: 100%;\n  padding: 50px;\n  border: none;\n  border-radius: 0;\n  margin: 0;\n}\n\nh1 {\n  margin-bottom: 20px;\n}\n\np {\n  line-height: 1.6;\n}\n\nhr {\n  margin: 20px 0;\n  border: 0;\n  border-top: 1px solid #ccc;\n}\n\nbutton {\n  padding: 10px 15px;\n  border: none;\n  border-radius: 5px;\n  background: #333;\n  color: white;\n  cursor: pointer;\n}\n\nbutton:hover {\n  background: #555;\n}\n\ncode {\n  background: #eee;\n  padding: 2px 5px;\n  border-radius: 3px;\n}\n\n@media (max-width: 600px) {\n  .container {\n    padding: 25px;\n  }\n\n  h1 {\n    font-size: 25px;\n  }\n}",
      "Main.jsx": "import React from \"react\";\nimport ReactDOM from \"react-dom/client\";\nimport App from \"./App\";\nimport \"./index.css\";\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(\n  <React.StrictMode>\n    <App />\n  </React.StrictMode>\n);\n"
    }
  }
