export default function App() {
  const [selectedId, setSelectedId] = useState(1);
  const [selectedFile, setSelectedFile] = useState('App.jsx');
  const [searchQuery, setSearchQuery] = useState('');
  const [copied, setCopied] = useState(false);

  const filteredPracticals = practicalsData.filter(p => {
    const query = searchQuery.toLowerCase();
    return (
      p.num.includes(query) ||
      p.title.toLowerCase().includes(query) ||
      p.description.toLowerCase().includes(query) ||
      (p.id.toString() === query.trim())
    );
  });

  const currentPractical = practicalsData.find(p => p.id === selectedId) || practicalsData[0];
  const fileNames = Object.keys(currentPractical.files);
  
  // Ensure selectedFile is valid for current practical
  const activeFile = fileNames.includes(selectedFile) ? selectedFile : fileNames[0];
  const currentCode = currentPractical.files[activeFile] || '// No code available';

  const handleSelectPractical = (id) => {
    setSelectedId(id);
    const targetP = practicalsData.find(p => p.id === id);
    if (targetP && !Object.keys(targetP.files).includes(selectedFile)) {
      setSelectedFile(Object.keys(targetP.files)[0] || 'App.jsx');
    }
  };

  const handleCopy = () => {
    if (navigator.clipboard) {
      navigator.clipboard.writeText(currentCode).then(() => {
        setCopied(true);
        setTimeout(() => setCopied(false), 1500);
      });
    }
  };

  return (
    <div>
      {/* Header */}
      <header className="app-header">
        <div className="header-title">
          <h1>ReactJS Practicals Reference</h1>
          <p>B.Sc. IT | ReactJS Practical Code Book</p>
        </div>
        <div className="student-info-badge">
          <div><strong>Name:</strong> Chandan Gopal Tiwadi</div>
          <div><strong>Roll No.:</strong> 57 | <strong>Age:</strong> 20</div>
          <div><strong>Course:</strong> B.Sc. IT | <strong>Subject:</strong> ReactJs</div>
        </div>
      </header>

      {/* Main Layout */}
      <div className="layout-container">
        {/* Sidebar */}
        <aside className="sidebar">
          <input
            type="text"
            className="search-input"
            placeholder="Search practicals (e.g. useState, Router, API)..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />

          <ul className="practicals-list">
            {filteredPracticals.map(p => (
              <li
                key={p.id}
                className={`practical-item ${p.id === currentPractical.id ? 'active' : ''}`}
                onClick={() => handleSelectPractical(p.id)}
              >
                <span className="practical-badge">{p.num}</span>
                <span>{p.title}</span>
              </li>
            ))}
            {filteredPracticals.length === 0 && (
              <li style={{ padding: '12px', color: '#64748b', fontSize: '13px', textAlign: 'center' }}>
                No practicals match your search.
              </li>
            )}
          </ul>
        </aside>

        {/* Content View */}
        <main className="main-content">
          <div className="practical-header">
            <h2>Practical {currentPractical.num}: {currentPractical.title}</h2>
            <div className="practical-description">
              <strong>Question / Objective:</strong> {currentPractical.description}
            </div>
          </div>

          <div>
            <div className="viewer-top-bar">
              <div className="tabs-container">
                {fileNames.map(fileName => (
                  <button
                    key={fileName}
                    className={`tab-button ${fileName === activeFile ? 'active' : ''}`}
                    onClick={() => setSelectedFile(fileName)}
                  >
                    {fileName}
                  </button>
                ))}
              </div>
              <button
                className={`copy-button ${copied ? 'copied' : ''}`}
                onClick={handleCopy}
              >
                {copied ? 'Copied!' : 'Copy Code'}
              </button>
            </div>

            <div className="code-container">
              <pre className="code-block">
                <code>{currentCode}</code>
              </pre>
            </div>
          </div>
        </main>
      </div>
    </div>
  );
}
